const std::string DEF_TAU = "(def TAU 6.28318531)";

const std::string NS_PIXILS_POINT = R"(
  (ns pixils.point)
                                     )";

const std::string DEFUN_PT_PLUS = R"(
(defun plus [p1 p2]
  {:x (+ (:x p1) (:x p2))
   :y (+ (:y p1) (:y p2))})
                                   )";

const std::string DEFUN_PT_DIV = R"(
(defun div [p n]
  {:x (/ (:x p) n)
   :y (/ (:y p) n)})
                                   )";

const std::string DEFUN_PT_ROTATE = R"(
(defun rotate [p amount]
  (let [s (sin amount)
        c (cos amount)]
    {:x (- (* (:x p) c) (* (:y p) s))
     :y (+ (* (:x p) s) (* (:y p) c))}))
                                     )";

const std::string DEFUN_PT_DISTANCE = R"(
(defun distance [p1 p2]
  (sqrt (+ (* (- (:x p2) (:x p1)) (- (:x p2) (:x p1)))
           (* (- (:y p2) (:y p1)) (- (:y p2) (:y p1))))))
                                       )";

const std::string PIXILS__POINT =
  NS_PIXILS_POINT + DEFUN_PT_PLUS + DEFUN_PT_DIV + DEFUN_PT_ROTATE + DEFUN_PT_DISTANCE;

const std::string NS_ASTEROIDS_ASTEROID = R"(
(ns asteroids.asteroid
  (:require [pixils.point :as pt]))
                                           )";

const std::string DEF_ASTEROID_TYPES = R"(
(def ASTEROID-TYPES
  {:large {:shape {:base-radius 20
                   :points 12}
           :movement {:rate -1}
           :score 50
           :yield [:mid :mid]
           :explosion {:particle-count 560
                       :velocity-mod 30
                       :radius 15}}
   :mid {:shape {:base-radius 13
                 :points 9}
         :movement {:rate -1.5}
         :score 100
         :yield [:small :small]
         :explosion {:particle-count 400
                     :velocity-mod 35
                     :radius 12}}
   :small {:shape {:base-radius 7
                   :points 8}
           :movement {:rate -2}
           :score 150
           :yield []
           :explosion {:particle-count 140
                       :velocity-mod 45
                       :radius 9}}})

                                    )";

const std::string DEFUN_MAKE_ASTEROID_SHAPE = R"(
(defun make-asteroid-shape [size points]
  (let [pt {:x 0 :y (- 0 size) }
        step-size (/ TAU points)]
    (map (range 1 points)
         (fn [i] (pt/rotate (pt/plus pt
                                     {:x 0 :y (rnd (/ (abs (:y pt)) 2))})
                            (+ (* i step-size)
                               (/ (rnd (* 25 step-size)) 100)))))))
                                               )";

const std::string DEFUN_MAKE_ASTEROID = R"(
(defun make-asteroid [{:keys [type pos]} area]
  (let [{:keys [base-radius points]} (-> ASTEROID-TYPES (get type) :shape)]
    {:shape (make-asteroid-shape base-radius points)
     :size type
     :rotation (/ (rnd (* 100 TAU)) 100)
     :rotation-factor (rand-nth [0.03 -0.03])
     :pos (or pos {:x (rnd (:w area)) :y (rnd (:h area))})
     :move (pt/rotate {:x 0 :y -1} (/ (rnd (* 100 TAU)) 100))}))
                                         )";

const std::string DEFUN_SPLIT_ASTEROID = R"(
(defun split-asteroid [rock area]
  (cond
    (= :large (:size rock))
    [(make-asteroid {:pos (:pos rock) :type :mid} area)
     (make-asteroid {:pos (:pos rock) :type :mid} area)]

    (= :mid (:size rock))
    [(make-asteroid {:pos (:pos rock) :type :small} area)
     (make-asteroid {:pos (:pos rock) :type :small} area)]

    true
    []))
                                          )";

const std::string ASTEROIDS__ASTEROID = NS_ASTEROIDS_ASTEROID + DEF_TAU +
                                        DEF_ASTEROID_TYPES + DEFUN_MAKE_ASTEROID_SHAPE +
                                        DEFUN_MAKE_ASTEROID + DEFUN_SPLIT_ASTEROID;

const std::string NS_ASTEROIDS_DEBRIS = R"(
(ns asteroids.debris
  (:require [pixils.point :as pt]))
                                     )";

const std::string DEF_PARTICLE_COLORS = R"(
(def PARTICLE-COLORS [{:r 255 :g 255 :b 255}
                      {:r 255 :g 250 :b 200}
                      {:r 255 :g 245 :b 170}

                      {:r 255 :g 235 :b 120}
                      {:r 255 :g 220 :b 90}
                      {:r 255 :g 200 :b 60}

                      {:r 255 :g 170 :b 40}
                      {:r 255 :g 140 :b 20}
                      {:r 255 :g 110 :b 10}

                      {:r 220 :g 60 :b 10}
                      {:r 190 :g 40 :b 0}
                      {:r 150 :g 20 :b 0}])
                                         )";

const std::string DEFUN_MAKE_DEBRIS = R"(
(defun make-debris [origin {:keys [particle-count velocity-mod radius move-mod]}]
  (map (range 1 particle-count)
       (fn [n]
         (let [countdown (rnd 25 55)
               dir (/ (rnd (* 100 TAU)) 100)]
           {:pos (pt/plus origin
                       (pt/rotate {:x 0 :y (- 0 (rnd radius))} dir))
            :move
            (pt/plus
             (pt/rotate {:x 0 :y (- 0 (+ 0.1 (/ (rnd 50) velocity-mod)))}
                        dir)
             move-mod)
            :color (rand-nth PARTICLE-COLORS)
            :countdown-max countdown
            :countdown countdown }))))
                                       )";

const std::string ASTEROIDS__DEBRIS =
  NS_ASTEROIDS_DEBRIS + DEF_TAU + DEF_PARTICLE_COLORS + DEFUN_MAKE_DEBRIS;

const std::string NS_ASTEROIDS_COLLISION = R"(
(ns asteroids.collision
  (:require [pixils.point :as pt]
            [asteroids.debris :as debris]
            [asteroids.asteroid :as asteroid])))";

const std::string HANDLE_COLLISIONS_BODY = R"(
  (let [result
        (reduce asteroids
                {:player player
                 :asteroids []
                 :new-particles []}
                (fn [acc rock]
                  (let [type (get asteroid/ASTEROID-TYPES (:size rock))
                        player (:player acc)
                        bullets (:bullets player)]
                    (if-let [bullet-index (find-index bullets
                                                      (fn [bullet]
                                                        (<= (pt/distance (:pos rock)
                                                                         (:pos bullet))
                                                            (-> type :shape :base-radius))))]
                      (-> acc
                          (assoc :new-particles
                                 (concat (:new-particles acc)
                                         (debris/make-debris
                                          (:pos rock)
                                          (assoc (:explosion type)
                                                 :move-mod
                                                 (pt/plus (:move rock)
                                                       (pt/div
                                                        (:move (nth (-> acc
                                                                        :player
                                                                        :bullets) bullet-index))
                                                        5))))))
                          (assoc :asteroids (concat (:asteroids acc) (asteroid/split-asteroid rock area)))
                          (assoc :player (-> player
                                             (assoc :bullets (remove-nth (:bullets player) bullet-index))
                                             (assoc :score (+ (:score player)
                                                              (:score type))))))
                      (if (and (not (:destroyed player))
                               (<= (pt/distance (:pos rock)
                                                (-> player :ship :pos))
                                   (-> type :shape :base-radius)))
                        (-> acc
                            (assoc :new-particles (concat (:new-particles acc)
                                                          (debris/make-debris (-> player :ship :pos)
                                                                              {:particle-count 400
                                                                               :velocity-mod 35
                                                                               :radius 12
                                                                               :move-mod
                                                                               (pt/plus (-> player :ship :acceleration)
                                                                                        (pt/div (:move rock) 2))})))
                            (assoc :player (assoc player :destroyed true))
                            (assoc :asteroids (concat (:asteroids acc)
                                                      rock)))
                        (assoc acc :asteroids (concat (:asteroids acc)
                                                      rock)))))))]
    (-> state
        (assoc :asteroids (:asteroids result))
        (assoc :particles (if (> (count (:new-particles result)) 0)
                            (concat (:particles state)
                                    (:new-particles result))
                            (:particles state)))
        (assoc :player (:player result))))
                                            )";

const std::string DEFUN_HANDLE_COLLISIONS =
  "(defun handle-collisions [{:keys [player asteroids particles] :as state} area]\n" +
  HANDLE_COLLISIONS_BODY + ")\n\n";

const std::string ASTEROIDS__COLLISION = NS_ASTEROIDS_COLLISION + DEFUN_HANDLE_COLLISIONS;

