TEST(Benchmark_Workload, benchmark_handle_collisions_funcall_1000_argset_1)
{
  LispleTest::SnippetBenchmark bm("workload_1000_handle_collisions__funcall_argset_1",
                                  {
                                    PIXILS__POINT,
                                    ASTEROIDS__ASTEROID,
                                    ASTEROIDS__DEBRIS,
                                    ASTEROIDS__COLLISION + DEF_AREA + DEF_ARG_SET_1,
                                  },
                                  "asteroids.collision",
                                  R"(
(dotimes [1000] (handle-collisions {:player player
                                    :asteroids asteroids
                                    :particles particles} area))
                                     )");
  bm.run();
}

